// SQLite access via better-sqlite3. The connection is opened lazily on first
// use so tests can set FEESAATHI_DB (e.g. ':memory:') before anything runs.
import Database from 'better-sqlite3';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const DEFAULT_DB_FILE = path.resolve(here, '../data/feesaathi.db');

let db = null;

function migrate(conn) {
  conn.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      email TEXT NOT NULL UNIQUE,
      password_hash TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS tutor_profiles (
      user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
      business_name TEXT,
      mobile TEXT,
      city_or_area TEXT,
      currency TEXT NOT NULL DEFAULT 'INR',
      opening_cash_balance REAL NOT NULL DEFAULT 0,
      fee_cycle TEXT NOT NULL DEFAULT 'monthly'
        CHECK (fee_cycle IN ('monthly','weekly','per_class','custom')),
      email TEXT,
      onboarded INTEGER NOT NULL DEFAULT 0,
      updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS password_reset_tokens (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      token_hash TEXT NOT NULL,
      expires_at INTEGER NOT NULL,          -- epoch milliseconds
      used INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE INDEX IF NOT EXISTS idx_reset_token_hash ON password_reset_tokens(token_hash);
  `);
}

export function getDb() {
  if (db) return db;
  const file = process.env.FEESAATHI_DB || DEFAULT_DB_FILE;
  if (file !== ':memory:') {
    fs.mkdirSync(path.dirname(file), { recursive: true });
  }
  db = new Database(file);
  db.pragma('foreign_keys = ON');
  migrate(db);
  return db;
}

// Password hashing, JWT session cookies and the requireAuth middleware.
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';

export const COOKIE_NAME = 'fs_token';
const DEV_SECRET = 'dev-only-insecure-secret';
const SECRET = process.env.JWT_SECRET || DEV_SECRET;
const SESSION_TTL_MS = 7 * 24 * 60 * 60 * 1000;

if (!process.env.JWT_SECRET) {
  console.warn('[auth] JWT_SECRET is not set. Using a dev-only insecure fallback secret. Do NOT use in production.');
}

const baseCookie = { httpOnly: true, sameSite: 'lax', path: '/' };

export const hashPassword = (password) => bcrypt.hashSync(password, 10);
export const verifyPassword = (password, hash) => bcrypt.compareSync(password, hash);

export function setAuthCookie(res, userId) {
  const token = jwt.sign({ sub: String(userId) }, SECRET, { expiresIn: '7d' });
  res.cookie(COOKIE_NAME, token, { ...baseCookie, maxAge: SESSION_TTL_MS });
}

export function clearAuthCookie(res) {
  res.clearCookie(COOKIE_NAME, baseCookie);
}

// Reads the session cookie, verifies it and sets req.userId. Responds 401 otherwise.
export function requireAuth(req, res, next) {
  const token = req.cookies?.[COOKIE_NAME];
  if (!token) return res.status(401).json({ error: 'Authentication required' });
  try {
    const payload = jwt.verify(token, SECRET);
    req.userId = Number(payload.sub);
    return next();
  } catch {
    return res.status(401).json({ error: 'Session is invalid or expired' });
  }
}

