// Auth routes: register, login, logout, password reset and session lookup.
import { Router } from 'express';
import crypto from 'node:crypto';
import { getDb } from '../db.js';
import { hashPassword, verifyPassword, setAuthCookie, clearAuthCookie, requireAuth } from '../auth.js';

const router = Router();
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const RESET_TTL_MS = 30 * 60 * 1000;
const IS_PROD = process.env.NODE_ENV === 'production';
const GENERIC_RESET_MSG = 'If an account exists for that email, password reset instructions have been sent.';

const str = (v) => (typeof v === 'string' ? v.trim() : '');
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');

export function publicUser(row) {
  return { id: row.id, name: row.name, email: row.email, createdAt: row.created_at };
}

export function toProfile(row) {
  if (!row) return null;
  return {
    businessName: row.business_name,
    mobile: row.mobile,
    cityOrArea: row.city_or_area,
    currency: row.currency,
    openingCashBalance: row.opening_cash_balance,
    feeCycle: row.fee_cycle,
    email: row.email,
    onboarded: !!row.onboarded,
    updatedAt: row.updated_at,
  };
}

// POST /api/auth/register
router.post('/register', (req, res) => {
  const name = str(req.body?.name);
  const email = str(req.body?.email).toLowerCase();
  const password = typeof req.body?.password === 'string' ? req.body.password : '';

  const errors = {};
  if (!name) errors.name = 'Name is required';
  if (!EMAIL_RE.test(email)) errors.email = 'Enter a valid email address';
  if (password.length < 8) errors.password = 'Password must be at least 8 characters';
  if (Object.keys(errors).length) {
    return res.status(400).json({ error: 'Validation failed', errors });
  }

  const db = getDb();
  if (db.prepare('SELECT 1 FROM users WHERE email = ?').get(email)) {
    return res.status(409).json({
      error: 'An account with this email already exists',
      errors: { email: 'An account with this email already exists' },
    });
  }

  const passwordHash = hashPassword(password);
  // Create the user and an empty profile atomically.
  const createUser = db.transaction(() => {
    const info = db
      .prepare('INSERT INTO users (name, email, password_hash) VALUES (?, ?, ?)')
      .run(name, email, passwordHash);
    db.prepare('INSERT INTO tutor_profiles (user_id, email) VALUES (?, ?)').run(info.lastInsertRowid, email);
    return info.lastInsertRowid;
  });

  let userId;
  try {
    userId = createUser();
  } catch (err) {
    if (err.code === 'SQLITE_CONSTRAINT_UNIQUE') {
      return res.status(409).json({
        error: 'An account with this email already exists',
        errors: { email: 'An account with this email already exists' },
      });
    }
    throw err;
  }

  setAuthCookie(res, userId);
  const user = db.prepare('SELECT * FROM users WHERE id = ?').get(userId);
  return res.status(201).json({ user: publicUser(user) });
});

// POST /api/auth/login
router.post('/login', (req, res) => {
  const email = str(req.body?.email).toLowerCase();
  const password = typeof req.body?.password === 'string' ? req.body.password : '';
  const db = getDb();
  const user = email ? db.prepare('SELECT * FROM users WHERE email = ?').get(email) : undefined;

  if (!user || !verifyPassword(password, user.password_hash)) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }
  setAuthCookie(res, user.id);
  return res.json({ user: publicUser(user) });
});

// POST /api/auth/logout
router.post('/logout', (req, res) => {
  clearAuthCookie(res);
  res.json({ ok: true });
});

// POST /api/auth/forgot-password
// Always answers generically so the endpoint does not reveal which emails exist.
router.post('/forgot-password', (req, res) => {
  const email = str(req.body?.email).toLowerCase();
  const db = getDb();
  const user = email ? db.prepare('SELECT id FROM users WHERE email = ?').get(email) : undefined;
  const body = { message: GENERIC_RESET_MSG };

  if (user) {
    const token = crypto.randomBytes(32).toString('base64url');
    db.prepare('INSERT INTO password_reset_tokens (user_id, token_hash, expires_at) VALUES (?, ?, ?)')
      .run(user.id, sha256(token), Date.now() + RESET_TTL_MS);

    // NOTE: no email provider is configured yet. In non-production builds the
    // token is returned in the response and logged so the flow can be tested.
    if (!IS_PROD) {
      body.resetToken = token;
      console.log(`[dev] Password reset token for ${email}: ${token} (expires in 30 min)`);
    }
  }
  return res.json(body);
});

// POST /api/auth/reset-password
router.post('/reset-password', (req, res) => {
  const token = str(req.body?.token);
  const newPassword = typeof req.body?.newPassword === 'string' ? req.body.newPassword : '';

  const errors = {};
  if (!token) errors.token = 'Reset token is required';
  if (newPassword.length < 8) errors.newPassword = 'Password must be at least 8 characters';
  if (Object.keys(errors).length) {
    return res.status(400).json({ error: 'Validation failed', errors });
  }

  const db = getDb();
  const row = db
    .prepare('SELECT * FROM password_reset_tokens WHERE token_hash = ? AND used = 0')
    .get(sha256(token));
  if (!row || row.expires_at < Date.now()) {
    return res.status(400).json({ error: 'Reset link is invalid or has expired' });
  }

  db.transaction(() => {
    db.prepare('UPDATE users SET password_hash = ? WHERE id = ?').run(hashPassword(newPassword), row.user_id);
    db.prepare('UPDATE password_reset_tokens SET used = 1 WHERE user_id = ?').run(row.user_id);
  })();

  return res.json({ message: 'Password updated. You can now sign in.' });
});

// GET /api/auth/me
router.get('/me', requireAuth, (req, res) => {
  const db = getDb();
  const user = db.prepare('SELECT * FROM users WHERE id = ?').get(req.userId);
  if (!user) return res.status(401).json({ error: 'Authentication required' });
  const profile = db.prepare('SELECT * FROM tutor_profiles WHERE user_id = ?').get(user.id);
  return res.json({ user: publicUser(user), profile: toProfile(profile) });
});

export default router;

// Tutor onboarding: stores business details and marks the profile as onboarded.
import { Router } from 'express';
import { getDb } from '../db.js';
import { publicUser, toProfile } from './auth.js';

const router = Router();
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const CURRENCIES = ['INR', 'USD', 'EUR', 'GBP', 'AED'];
const FEE_CYCLES = ['monthly', 'weekly', 'per_class', 'custom'];

const str = (v) => (typeof v === 'string' ? v.trim() : '');
const orDefault = (v, fallback) => (v === undefined || v === null || v === '' ? fallback : v);

// Accepts "9876543210", "98765 43210" or "+91 98765 43210"; returns the bare 10 digits.
function normalizeMobile(raw) {
  let s = str(raw).replace(/\s+/g, '');
  if (s.startsWith('+91')) s = s.slice(3);
  return s;
}

// POST /api/onboarding  (mounted behind requireAuth in app.js)
router.post('/', (req, res) => {
  const b = req.body || {};
  const errors = {};

  const name = str(b.name);
  if (!name) errors.name = 'Your name is required';
  else if (name.length > 100) errors.name = 'Name must be 100 characters or fewer';

  const businessName = str(b.businessName) || null;
  if (businessName && businessName.length > 120) errors.businessName = 'Business name must be 120 characters or fewer';

  const mobile = normalizeMobile(b.mobile);
  if (!mobile) errors.mobile = 'Mobile number is required';
  else if (!/^[6-9]\d{9}$/.test(mobile)) errors.mobile = 'Enter a valid 10-digit mobile number';

  const email = str(b.email).toLowerCase();
  if (!email) errors.email = 'Email is required';
  else if (!EMAIL_RE.test(email)) errors.email = 'Enter a valid email address';

  const cityOrArea = str(b.cityOrArea) || null;

  const currency = orDefault(b.currency, 'INR');
  if (!CURRENCIES.includes(currency)) errors.currency = `Currency must be one of ${CURRENCIES.join(', ')}`;

  let openingCashBalance = 0;
  const rawOpening = orDefault(b.openingCashBalance, 0);
  if (typeof rawOpening === 'number' || typeof rawOpening === 'string') {
    openingCashBalance = Number(rawOpening);
  }
  if (!Number.isFinite(openingCashBalance) || openingCashBalance < 0) {
    errors.openingCashBalance = 'Opening cash balance must be a number of 0 or more';
  }

  const feeCycle = orDefault(b.feeCycle, 'monthly');
  if (!FEE_CYCLES.includes(feeCycle)) errors.feeCycle = `Fee cycle must be one of ${FEE_CYCLES.join(', ')}`;

  if (Object.keys(errors).length) {
    return res.status(400).json({ error: 'Validation failed', errors });
  }

  const db = getDb();
  const userId = req.userId;

  const clash = db.prepare('SELECT id FROM users WHERE email = ? AND id <> ?').get(email, userId);
  if (clash) {
    return res.status(400).json({
      error: 'Validation failed',
      errors: { email: 'This email is already used by another account' },
    });
  }

  db.transaction(() => {
    db.prepare('UPDATE users SET name = ?, email = ? WHERE id = ?').run(name, email, userId);
    db.prepare(`
      INSERT INTO tutor_profiles
        (user_id, business_name, mobile, city_or_area, currency, opening_cash_balance,
         fee_cycle, email, onboarded, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, datetime('now'))
      ON CONFLICT(user_id) DO UPDATE SET
        business_name = excluded.business_name,
        mobile = excluded.mobile,
        city_or_area = excluded.city_or_area,
        currency = excluded.currency,
        opening_cash_balance = excluded.opening_cash_balance,
        fee_cycle = excluded.fee_cycle,
        email = excluded.email,
        onboarded = 1,
        updated_at = excluded.updated_at
    `).run(userId, businessName, mobile, cityOrArea, currency, openingCashBalance, feeCycle, email);
  })();

  const user = db.prepare('SELECT * FROM users WHERE id = ?').get(userId);
  const profile = db.prepare('SELECT * FROM tutor_profiles WHERE user_id = ?').get(userId);
  return res.json({ user: publicUser(user), profile: toProfile(profile) });
});

export default router;

// Express app factory. Kept separate from index.js so tests can mount it on an ephemeral port.
import express from 'express';
import cookieParser from 'cookie-parser';
import authRouter from './routes/auth.js';
import onboardingRouter from './routes/onboarding.js';
import { requireAuth } from './auth.js';

export function createApp() {
  const app = express();
  app.disable('x-powered-by');
  app.use(express.json());
  app.use(cookieParser());

  // Public routes
  app.get('/api/health', (req, res) => res.json({ ok: true }));
  app.use('/api/auth', authRouter);

  // Protected routes
  app.use('/api/onboarding', requireAuth, onboardingRouter);

  // JSON 404 for any other /api route
  app.use('/api', (req, res) => {
    res.status(404).json({ error: `Not found: ${req.method} ${req.originalUrl}` });
  });

  // JSON error handler
  // eslint-disable-next-line no-unused-vars
  app.use((err, req, res, next) => {
    if (res.headersSent) return next(err);
    let status = err.status || err.statusCode || 500;
    if (err.code === 'SQLITE_CONSTRAINT_UNIQUE') status = 409;
    if (status >= 500) {
      console.error(err);
      return res.status(500).json({ error: 'Internal server error' });
    }
    return res.status(status).json({ error: err.message });
  });

  return app;
}

// Entry point: starts the HTTP server.
import { createApp } from './app.js';

const port = Number(process.env.PORT) || 4000;

createApp().listen(port, () => {
  console.log(`FeeSaathi API listening at http://localhost:${port}`);
});

// API tests using node:test and fetch against an ephemeral-port server.
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';

// Set env before the app (and therefore db.js) is loaded.
process.env.FEESAATHI_DB = ':memory:';
process.env.JWT_SECRET ??= 'test-secret';

const { createApp } = await import('../src/app.js');

let server;
let base;
let cookie;

before(async () => {
  server = createApp().listen(0);
  await new Promise((resolve) => server.once('listening', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
});

after(() => new Promise((resolve) => server.close(resolve)));

const post = (path, body, headers = {}) =>
  fetch(base + path, {
    method: 'POST',
    headers: { 'content-type': 'application/json', ...headers },
    body: JSON.stringify(body),
  });

const get = (path, headers = {}) => fetch(base + path, { headers });

const cookieFrom = (res) => (res.headers.get('set-cookie') || '').split(';')[0];

const EMAIL = 'asha@example.com';
const PASSWORD = 'password123';

test('register creates a user and sets the session cookie', async () => {
  const res = await post('/api/auth/register', {
    name: 'Asha Verma',
    email: 'Asha@Example.com',
    password: PASSWORD,
  });
  assert.equal(res.status, 201);
  const body = await res.json();
  assert.equal(body.user.email, EMAIL);
  assert.match(res.headers.get('set-cookie'), /fs_token=/);
});

test('duplicate register returns 409', async () => {
  const res = await post('/api/auth/register', {
    name: 'Someone Else',
    email: EMAIL,
    password: PASSWORD,
  });
  assert.equal(res.status, 409);
});

test('register validation returns field errors', async () => {
  const res = await post('/api/auth/register', { name: '', email: 'not-an-email', password: 'short' });
  assert.equal(res.status, 400);
  const body = await res.json();
  assert.ok(body.errors.name);
  assert.ok(body.errors.email);
  assert.ok(body.errors.password);
});

test('login succeeds with correct credentials', async () => {
  const res = await post('/api/auth/login', { email: EMAIL, password: PASSWORD });
  assert.equal(res.status, 200);
  cookie = cookieFrom(res);
  assert.match(cookie, /^fs_token=/);
});

test('login with wrong password returns 401', async () => {
  const res = await post('/api/auth/login', { email: EMAIL, password: 'wrong-password' });
  assert.equal(res.status, 401);
  assert.equal((await res.json()).error, 'Invalid email or password');
});

test('onboarding rejects an invalid mobile number', async () => {
  const res = await post(
    '/api/onboarding',
    { name: 'Asha', email: EMAIL, mobile: '12345', feeCycle: 'monthly' },
    { cookie },
  );
  assert.equal(res.status, 400);
  const body = await res.json();
  assert.ok(body.errors.mobile);
});

test('onboarding rejects an invalid fee cycle', async () => {
  const res = await post(
    '/api/onboarding',
    { name: 'Asha', email: EMAIL, mobile: '9876543210', feeCycle: 'yearly' },
    { cookie },
  );
  assert.equal(res.status, 400);
  const body = await res.json();
  assert.ok(body.errors.feeCycle);
});

test('onboarding succeeds and marks the profile onboarded', async () => {
  const res = await post(
    '/api/onboarding',
    {
      name: 'Asha Verma',
      businessName: 'Asha Tuition Centre',
      mobile: '+91 98765 43210',
      email: EMAIL,
      cityOrArea: 'Pune',
      currency: 'INR',
      openingCashBalance: 2500,
      feeCycle: 'monthly',
    },
    { cookie },
  );
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.profile.onboarded, true);
  assert.equal(body.profile.mobile, '9876543210');
  assert.equal(body.profile.openingCashBalance, 2500);
});

