// Pure invoice rules: totals, derived status, numbering and balances. No database access.

// Rounds to 2 decimal places (money).
export const round2 = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;

// total = base + additional - discount. Returns { total } or { error }.
export function computeTotal({ base_amount, additional_charges = 0, discount = 0 }) {
  const subtotal = round2(Number(base_amount) + Number(additional_charges));
  const disc = round2(Number(discount));
  if (disc > subtotal) return { error: 'Discount cannot exceed base plus additional charges' };
  const total = round2(subtotal - disc);
  if (total < 0) return { error: 'Total cannot be negative' };
  return { total };
}

// Derives the status shown to the user. Dates are YYYY-MM-DD strings.
export function computeStatus({ total, paid, dueDate, cancelled, today, storedStatus }) {
  if (cancelled) return 'cancelled';
  const remaining = round2(total - paid);
  if (remaining <= 0) return 'paid';
  if (today > dueDate) return 'overdue';
  if (paid > 0) return 'partially_paid';
  if (storedStatus === 'draft') return 'draft';
  if (storedStatus === 'sent') return 'sent';
  return 'pending';
}

// FS-YYYY-NNNN, where NNNN is the sequence after the highest existing one.
export function nextInvoiceNumber(existingMaxSeq, year) {
  return `FS-${year}-${String(existingMaxSeq + 1).padStart(4, '0')}`;
}

export function remainingBalance(total, paid) {
  return round2(total - paid);
}

// Local calendar date as YYYY-MM-DD (the host's timezone, not UTC).
export function todayIso(date = new Date()) {
  const pad = (n) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

// Invoices: fee bills raised against a student. Totals are stored; paid amounts and statuses are
// derived from the payments table on every read. Mounted behind requireAuth, so req.userId is the tutor.
import { Router } from 'express';
import { getDb } from '../db.js';
import { computeTotal, computeStatus, nextInvoiceNumber, remainingBalance, round2, todayIso } from '../invoiceLogic.js';

const router = Router();
const INVOICE_TYPES = ['monthly', 'weekly', 'per_class', 'custom', 'additional'];
const STATUSES = ['draft', 'sent', 'pending', 'partially_paid', 'paid', 'overdue', 'cancelled'];
const OUTSTANDING = ['pending', 'sent', 'partially_paid', 'overdue'];
const NOT_FOUND = { message: 'Invoice not found' };

const text = (v) => (v === undefined || v === null ? '' : String(v).trim());

// Number from a number or numeric string; NaN otherwise.
function toNumber(v) {
  if (typeof v === 'number') return v;
  if (typeof v === 'string' && v.trim() !== '') return Number(v);
  return NaN;
}

// True for a real calendar date in YYYY-MM-DD form.
function isIsoDate(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const d = new Date(`${s}T00:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s;
}

// Validates an invoice in snake_case. `base` supplies values for fields not in the input
// (PUT passes the stored invoice so a partial update is checked as a whole).
// additional_charges is a list of { label, amount }. Returns { errors, values }.
function validate(input, base) {
  const b = { ...base };
  for (const key of Object.keys(input)) {
    if (input[key] !== undefined) b[key] = input[key];
  }

  const errors = {};
  const values = {};

  values.invoice_type = b.invoice_type;
  if (!INVOICE_TYPES.includes(b.invoice_type)) {
    errors.invoice_type = `Invoice type must be one of ${INVOICE_TYPES.join(', ')}`;
  }

  const period = text(b.billing_period);
  if (!period) errors.billing_period = 'Billing period is required';
  else if (period.length > 100) errors.billing_period = 'Billing period must be 100 characters or fewer';
  values.billing_period = period;

  const description = text(b.description);
  if (description.length > 500) errors.description = 'Description must be 500 characters or fewer';
  values.description = description || null;

  const issue = text(b.issue_date);
  if (!isIsoDate(issue)) errors.issue_date = 'Issue date must be in YYYY-MM-DD format';
  values.issue_date = issue;

  const due = text(b.due_date);
  if (!due) errors.due_date = 'Due date is required';
  else if (!isIsoDate(due)) errors.due_date = 'Due date must be in YYYY-MM-DD format';
  else if (isIsoDate(issue) && due < issue) errors.due_date = 'Due date cannot be before issue date';
  values.due_date = due;

  const baseAmount = toNumber(b.base_amount);
  if (!Number.isFinite(baseAmount) || baseAmount < 0) {
    errors.base_amount = 'Base amount must be a number of 0 or more';
  }
  values.base_amount = baseAmount;

  // Additional charges: a list of { label, amount }. Omitted or null means none.
  const rawItems = b.additional_charges ?? [];
  const items = [];
  if (!Array.isArray(rawItems)) {
    errors.additional_charges = 'Additional charges must be a list';
  } else {
    for (const item of rawItems) {
      const label = text(item?.label);
      const amount = toNumber(item?.amount);
      if (!label) {
        errors.additional_charges = 'Each additional charge needs a label';
        break;
      }
      if (label.length > 100) {
        errors.additional_charges = 'Additional charge labels must be 100 characters or fewer';
        break;
      }
      if (!Number.isFinite(amount) || amount < 0) {
        errors.additional_charges = 'Each additional charge needs an amount of 0 or more';
        break;
      }
      items.push({ label, amount });
    }
  }
  values.items = items;
  values.additional_total = round2(items.reduce((sum, item) => sum + item.amount, 0));

  const discount = b.discount === undefined || b.discount === null || b.discount === '' ? 0 : toNumber(b.discount);
  if (!Number.isFinite(discount) || discount < 0) errors.discount = 'Discount must be a number of 0 or more';
  values.discount = discount;

  // Total is only meaningful when the amounts themselves are valid.
  if (!errors.base_amount && !errors.additional_charges && !errors.discount) {
    const result = computeTotal({
      base_amount: baseAmount,
      additional_charges: values.additional_total,
      discount,
    });
    if (result.error) errors.discount = result.error;
    else values.total = result.total;
  }

  return { errors, values };
}

// Parses :id; returns the invoice row only if it belongs to the current user.
export function findOwnedInvoice(db, userId, rawId) {
  const id = Number(rawId);
  if (!Number.isInteger(id) || id <= 0) return undefined;
  return db.prepare('SELECT * FROM invoices WHERE id = ? AND user_id = ?').get(id, userId);
}

// Sum of active (not reversed) payments on an invoice.
export function paidAmount(db, invoiceId) {
  return db
    .prepare("SELECT COALESCE(SUM(amount), 0) AS paid FROM payments WHERE invoice_id = ? AND status = 'active'")
    .get(invoiceId).paid;
}

// The invoice as the API returns it: stored fields plus paid_amount, remaining_balance and derived status.
export function invoiceView(db, row) {
  const paid = paidAmount(db, row.id);
  return {
    ...row,
    paid_amount: round2(paid),
    remaining_balance: remainingBalance(row.total_amount, paid),
    status: computeStatus({
      total: row.total_amount,
      paid,
      dueDate: row.due_date,
      cancelled: row.status === 'cancelled' || row.cancelled_at != null,
      today: todayIso(),
      storedStatus: row.status,
    }),
  };
}

// Replaces the base and additional line items of an invoice.
function replaceItems(db, invoiceId, values) {
  db.prepare('DELETE FROM invoice_items WHERE invoice_id = ?').run(invoiceId);
  const add = db.prepare('INSERT INTO invoice_items (invoice_id, kind, label, amount) VALUES (?, ?, ?, ?)');
  add.run(invoiceId, 'base', 'Base fee', values.base_amount);
  for (const item of values.items) add.run(invoiceId, 'additional', item.label, item.amount);
}

// GET /api/invoices?status=&studentId=
router.get('/', (req, res) => {
  const errors = {};
  const status = req.query.status === undefined || req.query.status === '' ? null : String(req.query.status);
  if (status && !STATUSES.includes(status)) errors.status = `Status must be one of ${STATUSES.join(', ')}`;

  let studentId = null;
  if (req.query.studentId !== undefined && req.query.studentId !== '') {
    studentId = Number(req.query.studentId);
    if (!Number.isInteger(studentId) || studentId <= 0) errors.studentId = 'Student id must be a positive integer';
  }
  if (Object.keys(errors).length) {
    return res.status(400).json({ error: 'Validation failed', errors });
  }

  const db = getDb();
  const params = [req.userId];
  let sql = 'SELECT * FROM invoices WHERE user_id = ?';
  if (studentId !== null) {
    sql += ' AND student_id = ?';
    params.push(studentId);
  }
  sql += ' ORDER BY issue_date DESC, id DESC';

  const all = db.prepare(sql).all(...params).map((row) => invoiceView(db, row));
  const invoices = status ? all.filter((inv) => inv.status === status) : all;
  const outstanding_total = round2(
    invoices.filter((inv) => OUTSTANDING.includes(inv.status)).reduce((sum, inv) => sum + inv.remaining_balance, 0),
  );
  return res.json({ invoices, outstanding_total });
});

// POST /api/invoices
router.post('/', (req, res) => {
  const body = req.body || {};
  const db = getDb();

  const { errors, values } = validate(body, {
    issue_date: todayIso(),
    additional_charges: [],
    discount: 0,
  });

  const studentId = Number(body.student_id);
  if (!Number.isInteger(studentId) || studentId <= 0) {
    errors.student_id = 'Student is required';
  } else {
    const student = db.prepare('SELECT * FROM students WHERE id = ? AND user_id = ?').get(studentId, req.userId);
    if (!student) errors.student_id = 'Student not found';
    else if (student.status !== 'active') errors.student_id = 'Student is archived';
  }

  if (Object.keys(errors).length) {
    return res.status(400).json({ error: 'Validation failed', errors });
  }

  const initialStatus = body.status === 'draft' ? 'draft' : 'pending';
  const id = db.transaction(() => {
    const year = values.issue_date.slice(0, 4);
    const { maxSeq } = db
      .prepare(`
        SELECT COALESCE(MAX(CAST(SUBSTR(invoice_number, 9) AS INTEGER)), 0) AS maxSeq
        FROM invoices WHERE user_id = ? AND invoice_number LIKE ?
      `)
      .get(req.userId, `FS-${year}-%`);

    const info = db.prepare(`
      INSERT INTO invoices
        (user_id, student_id, invoice_number, billing_period, invoice_type, description, issue_date,
         due_date, base_amount, additional_charges, discount, total_amount, status, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
    `).run(
      req.userId,
      studentId,
      nextInvoiceNumber(maxSeq, year),
      values.billing_period,
      values.invoice_type,
      values.description,
      values.issue_date,
      values.due_date,
      values.base_amount,
      values.additional_total,
      values.discount,
      values.total,
      initialStatus,
    );
    replaceItems(db, info.lastInsertRowid, values);
    return info.lastInsertRowid;
  })();

  const invoice = db.prepare('SELECT * FROM invoices WHERE id = ?').get(id);
  return res.status(201).json({ invoice: invoiceView(db, invoice) });
});

// GET /api/invoices/:id
router.get('/:id', (req, res) => {
  const db = getDb();
  const row = findOwnedInvoice(db, req.userId, req.params.id);
  if (!row) return res.status(404).json(NOT_FOUND);

  const items = db.prepare('SELECT * FROM invoice_items WHERE invoice_id = ? ORDER BY id').all(row.id);
  const payments = db.prepare('SELECT * FROM payments WHERE invoice_id = ? ORDER BY id').all(row.id);
  return res.json({ invoice: invoiceView(db, row), items, payments });
});

// PUT /api/invoices/:id  (only drafts, or invoices with no payments yet)
router.put('/:id', (req, res) => {
  const db = getDb();
  const existing = findOwnedInvoice(db, req.userId, req.params.id);
  if (!existing) return res.status(404).json(NOT_FOUND);
  if (existing.status === 'cancelled') {
    return res.status(409).json({ message: 'Cancelled invoices cannot be edited' });
  }

  const hasPayments = db.prepare('SELECT COUNT(*) AS n FROM payments WHERE invoice_id = ?').get(existing.id).n > 0;
  if (existing.status !== 'draft' && hasPayments) {
    return res.status(409).json({ message: 'Invoice has payments; create a correction instead' });
  }

  const existingItems = db
    .prepare("SELECT label, amount FROM invoice_items WHERE invoice_id = ? AND kind = 'additional' ORDER BY id")
    .all(existing.id);
  const { errors, values } = validate(req.body || {}, { ...existing, additional_charges: existingItems });
  if (Object.keys(errors).length) {
    return res.status(400).json({ error: 'Validation failed', errors });
  }

  db.transaction(() => {
    db.prepare(`
      UPDATE invoices SET
        invoice_type = ?, billing_period = ?, description = ?, issue_date = ?, due_date = ?,
        base_amount = ?, additional_charges = ?, discount = ?, total_amount = ?, updated_at = datetime('now')
      WHERE id = ? AND user_id = ?
    `).run(
      values.invoice_type,
      values.billing_period,
      values.description,
      values.issue_date,
      values.due_date,
      values.base_amount,
      values.additional_total,
      values.discount,
      values.total,
      existing.id,
      req.userId,
    );
    replaceItems(db, existing.id, values);
  })();

  const row = db.prepare('SELECT * FROM invoices WHERE id = ?').get(existing.id);
  return res.json({ invoice: invoiceView(db, row) });
});

// POST /api/invoices/:id/send  (draft -> sent)
router.post('/:id/send', (req, res) => {
  const db = getDb();
  const existing = findOwnedInvoice(db, req.userId, req.params.id);
  if (!existing) return res.status(404).json(NOT_FOUND);
  if (existing.status !== 'draft') {
    return res.status(409).json({ message: 'Only draft invoices can be sent' });
  }

  db.prepare("UPDATE invoices SET status = 'sent', updated_at = datetime('now') WHERE id = ? AND user_id = ?")
    .run(existing.id, req.userId);
  const row = db.prepare('SELECT * FROM invoices WHERE id = ?').get(existing.id);
  return res.json({ invoice: invoiceView(db, row) });
});

// POST /api/invoices/:id/cancel  (kept in the database, excluded from outstanding totals)
router.post('/:id/cancel', (req, res) => {
  const db = getDb();
  const existing = findOwnedInvoice(db, req.userId, req.params.id);
  if (!existing) return res.status(404).json(NOT_FOUND);
  if (existing.status === 'cancelled') {
    return res.status(409).json({ message: 'Invoice is already cancelled' });
  }

  const active = db
    .prepare("SELECT COUNT(*) AS n FROM payments WHERE invoice_id = ? AND status = 'active'")
    .get(existing.id).n;
  if (active > 0) return res.status(409).json({ message: 'Reverse payments before cancelling' });

  db.prepare(`
    UPDATE invoices SET status = 'cancelled', cancelled_at = datetime('now'), updated_at = datetime('now')
    WHERE id = ? AND user_id = ?
  `).run(existing.id, req.userId);
  const row = db.prepare('SELECT * FROM invoices WHERE id = ?').get(existing.id);
  return res.json({ invoice: invoiceView(db, row) });
});

export default router;

// Payments: money received against an invoice. Payments are never deleted; corrections and
// reversals are recorded in payment_audit. Mounted behind requireAuth, so req.userId is the tutor.
import { Router } from 'express';
import { getDb } from '../db.js';
import { remainingBalance, round2, todayIso } from '../invoiceLogic.js';
import { findOwnedInvoice, invoiceView, isIsoDate, text, toNumber } from './invoices.js';

const router = Router();
const METHODS = ['cash', 'upi', 'bank_transfer', 'other'];
const NOT_FOUND = { message: 'Payment not found' };
const DUPLICATE_WINDOW = "-10 minutes";

// Parses :id; returns the payment row only if it belongs to the current user.
function findOwnedPayment(db, userId, rawId) {
  const id = Number(rawId);
  if (!Number.isInteger(id) || id <= 0) return undefined;
  return db.prepare('SELECT * FROM payments WHERE id = ? AND user_id = ?').get(id, userId);
}

// POST /api/payments
router.post('/', (req, res) => {
  const body = req.body || {};
  const db = getDb();
  const errors = {};

  const invoiceId = Number(body.invoice_id);
  if (!Number.isInteger(invoiceId) || invoiceId <= 0) errors.invoice_id = 'Invoice is required';

  const amount = toNumber(body.amount);
  if (!Number.isFinite(amount) || amount <= 0) errors.amount = 'Amount must be greater than 0';

  const rawDate = text(body.payment_date);
  const paymentDate = rawDate || todayIso();
  if (!isIsoDate(paymentDate)) errors.payment_date = 'Payment date must be in YYYY-MM-DD format';

  if (!METHODS.includes(body.method)) errors.method = `Method must be one of ${METHODS.join(', ')}`;

  const reference = text(body.reference);
  if (reference.length > 100) errors.reference = 'Reference must be 100 characters or fewer';
  const notes = text(body.notes);
  if (notes.length > 500) errors.notes = 'Notes must be 500 characters or fewer';

  if (Object.keys(errors).length) {
    return res.status(400).json({ error: 'Validation failed', errors });
  }

  const invoice = findOwnedInvoice(db, req.userId, invoiceId);
  if (!invoice) return res.status(404).json({ message: 'Invoice not found' });

  // Checks use the stored status: a past-due draft still shows as 'overdue' when derived.
  if (invoice.status === 'cancelled') errors.invoice_id = 'Invoice is cancelled';
  else if (invoice.status === 'draft') errors.invoice_id = 'Send the invoice before recording payments';

  const roundedAmount = round2(amount);
  if (!errors.invoice_id && roundedAmount > invoiceView(db, invoice).remaining_balance) {
    errors.amount = 'Amount exceeds remaining balance';
  }
  if (Object.keys(errors).length) {
    return res.status(400).json({ error: 'Validation failed', errors });
  }

  // Same invoice, amount, date and method within the last 10 minutes is probably a double submit.
  if (body.allow_duplicate !== true) {
    const dup = db.prepare(`
      SELECT id FROM payments
      WHERE invoice_id = ? AND user_id = ? AND status = 'active'
        AND amount = ? AND payment_date = ? AND method = ?
        AND created_at >= datetime('now', ?)
      LIMIT 1
    `).get(invoice.id, req.userId, roundedAmount, paymentDate, body.method, DUPLICATE_WINDOW);
    if (dup) return res.status(409).json({ message: 'Possible duplicate payment' });
  }

  const id = db.transaction(() => {
    const info = db.prepare(`
      INSERT INTO payments
        (user_id, student_id, invoice_id, amount, payment_date, method, reference, notes, status)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'active')
    `).run(
      req.userId,
      invoice.student_id,
      invoice.id,
      roundedAmount,
      paymentDate,
      body.method,
      reference || null,
      notes || null,
    );
    db.prepare(`
      INSERT INTO payment_audit (payment_id, action, old_amount, new_amount, reason)
      VALUES (?, 'created', NULL, ?, NULL)
    `).run(info.lastInsertRowid, roundedAmount);
    return info.lastInsertRowid;
  })();

  const payment = db.prepare('SELECT * FROM payments WHERE id = ?').get(id);
  const row = db.prepare('SELECT * FROM invoices WHERE id = ?').get(invoice.id);
  return res.status(201).json({ payment, invoice: invoiceView(db, row) });
});

// GET /api/payments?invoiceId=&studentId=  (active and reversed, each with its audit count)
router.get('/', (req, res) => {
  const errors = {};
  const idFilter = (name) => {
    const raw = req.query[name];
    if (raw === undefined || raw === '') return null;
    const n = Number(raw);
    if (!Number.isInteger(n) || n <= 0) {
      errors[name] = `${name} must be a positive integer`;
      return null;
    }
    return n;
  };
  const invoiceId = idFilter('invoiceId');
  const studentId = idFilter('studentId');
  if (Object.keys(errors).length) {
    return res.status(400).json({ error: 'Validation failed', errors });
  }

  const params = [req.userId];
  let sql = `
    SELECT p.*, (SELECT COUNT(*) FROM payment_audit a WHERE a.payment_id = p.id) AS audit_count
    FROM payments p WHERE p.user_id = ?
  `;
  if (invoiceId !== null) {
    sql += ' AND p.invoice_id = ?';
    params.push(invoiceId);
  }
  if (studentId !== null) {
    sql += ' AND p.student_id = ?';
    params.push(studentId);
  }
  sql += ' ORDER BY p.payment_date DESC, p.id DESC';

  const payments = getDb().prepare(sql).all(...params);
  return res.json({ payments });
});

// GET /api/payments/:id
router.get('/:id', (req, res) => {
  const db = getDb();
  const payment = findOwnedPayment(db, req.userId, req.params.id);
  if (!payment) return res.status(404).json(NOT_FOUND);
  const audit = db.prepare('SELECT * FROM payment_audit WHERE payment_id = ? ORDER BY id').all(payment.id);
  return res.json({ payment, audit });
});

// Returns the payment's invoice as a fresh view after a change.
function respondWithInvoice(db, res, payment, status = 200) {
  const updated = db.prepare('SELECT * FROM payments WHERE id = ?').get(payment.id);
  const row = db.prepare('SELECT * FROM invoices WHERE id = ?').get(payment.invoice_id);
  return res.status(status).json({ payment: updated, invoice: invoiceView(db, row) });
}

// POST /api/payments/:id/correct  body: { amount, reason }
router.post('/:id/correct', (req, res) => {
  const db = getDb();
  const payment = findOwnedPayment(db, req.userId, req.params.id);
  if (!payment) return res.status(404).json(NOT_FOUND);
  if (payment.status === 'reversed') {
    return res.status(409).json({ message: 'Reversed payments cannot be corrected' });
  }

  const body = req.body || {};
  const errors = {};
  const amount = toNumber(body.amount);
  if (!Number.isFinite(amount) || amount <= 0) errors.amount = 'Amount must be greater than 0';

  const reason = text(body.reason);
  if (reason.length < 3) errors.reason = 'Reason must be at least 3 characters';

  const invoice = db.prepare('SELECT * FROM invoices WHERE id = ?').get(payment.invoice_id);
  if (!errors.amount) {
    // The corrected amount may use the invoice total minus every other active payment.
    const others = db
      .prepare("SELECT COALESCE(SUM(amount), 0) AS s FROM payments WHERE invoice_id = ? AND status = 'active' AND id != ?")
      .get(invoice.id, payment.id).s;
    if (round2(amount) > remainingBalance(invoice.total_amount, others)) {
      errors.amount = 'Amount exceeds remaining balance';
    }
  }
  if (Object.keys(errors).length) {
    return res.status(400).json({ error: 'Validation failed', errors });
  }

  const newAmount = round2(amount);
  db.transaction(() => {
    db.prepare('UPDATE payments SET amount = ? WHERE id = ? AND user_id = ?')
      .run(newAmount, payment.id, req.userId);
    db.prepare(`
      INSERT INTO payment_audit (payment_id, action, old_amount, new_amount, reason)
      VALUES (?, 'corrected', ?, ?, ?)
    `).run(payment.id, payment.amount, newAmount, reason);
  })();

  return respondWithInvoice(db, res, payment);
});

// POST /api/payments/:id/reverse  body: { reason }
router.post('/:id/reverse', (req, res) => {
  const db = getDb();
  const payment = findOwnedPayment(db, req.userId, req.params.id);
  if (!payment) return res.status(404).json(NOT_FOUND);
  if (payment.status === 'reversed') {
    return res.status(409).json({ message: 'Payment is already reversed' });
  }

  const reason = text((req.body || {}).reason);
  if (!reason) {
    return res.status(400).json({ error: 'Validation failed', errors: { reason: 'Reason is required' } });
  }

  db.transaction(() => {
    db.prepare("UPDATE payments SET status = 'reversed' WHERE id = ? AND user_id = ?")
      .run(payment.id, req.userId);
    db.prepare(`
      INSERT INTO payment_audit (payment_id, action, old_amount, new_amount, reason)
      VALUES (?, 'reversed', ?, NULL, ?)
    `).run(payment.id, payment.amount, reason);
  })();

  return respondWithInvoice(db, res, payment);
});

export default router;

// Pure invoice rules: no server or database needed.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { computeTotal, computeStatus, nextInvoiceNumber, remainingBalance, todayIso } from '../src/invoiceLogic.js';

const FUTURE = '2099-01-01';
const PAST = '2000-01-10';
const TODAY = '2025-06-15';

test('total adds additional charges and subtracts discount', () => {
  assert.deepEqual(computeTotal({ base_amount: 1000, additional_charges: 200, discount: 100 }), { total: 1100 });
});

test('total is rounded to 2 decimal places', () => {
  assert.deepEqual(computeTotal({ base_amount: 0.1, additional_charges: 0.2, discount: 0 }), { total: 0.3 });
});

test('discount larger than base plus additional is rejected', () => {
  const result = computeTotal({ base_amount: 500, additional_charges: 0, discount: 600 });
  assert.equal(typeof result.error, 'string');
  assert.equal(result.total, undefined);
});

test('cancelled wins over every other status', () => {
  const status = computeStatus({ total: 100, paid: 0, dueDate: PAST, cancelled: true, today: TODAY, storedStatus: 'pending' });
  assert.equal(status, 'cancelled');
});

test('fully paid is paid even when past due', () => {
  const status = computeStatus({ total: 100, paid: 100, dueDate: PAST, cancelled: false, today: TODAY, storedStatus: 'pending' });
  assert.equal(status, 'paid');
});

test('past due with balance remaining is overdue, even after a partial payment', () => {
  const status = computeStatus({ total: 100, paid: 40, dueDate: PAST, cancelled: false, today: TODAY, storedStatus: 'pending' });
  assert.equal(status, 'overdue');
});

test('unpaid and past due is overdue', () => {
  const status = computeStatus({ total: 100, paid: 0, dueDate: PAST, cancelled: false, today: TODAY, storedStatus: 'sent' });
  assert.equal(status, 'overdue');
});

test('due today is not overdue', () => {
  const status = computeStatus({ total: 100, paid: 0, dueDate: TODAY, cancelled: false, today: TODAY, storedStatus: 'pending' });
  assert.equal(status, 'pending');
});

test('partial payment before the due date is partially_paid', () => {
  const status = computeStatus({ total: 100, paid: 40, dueDate: FUTURE, cancelled: false, today: TODAY, storedStatus: 'pending' });
  assert.equal(status, 'partially_paid');
});

test('stored draft and sent are kept when nothing is paid and not yet due', () => {
  assert.equal(computeStatus({ total: 100, paid: 0, dueDate: FUTURE, cancelled: false, today: TODAY, storedStatus: 'draft' }), 'draft');
  assert.equal(computeStatus({ total: 100, paid: 0, dueDate: FUTURE, cancelled: false, today: TODAY, storedStatus: 'sent' }), 'sent');
});

test('otherwise an unpaid invoice is pending', () => {
  const status = computeStatus({ total: 100, paid: 0, dueDate: FUTURE, cancelled: false, today: TODAY, storedStatus: 'pending' });
  assert.equal(status, 'pending');
});

test('invoice numbers are FS-YYYY-NNNN and follow the existing sequence', () => {
  assert.equal(nextInvoiceNumber(0, 2025), 'FS-2025-0001');
  assert.equal(nextInvoiceNumber(1, 2025), 'FS-2025-0002');
  assert.equal(nextInvoiceNumber(41, '2026'), 'FS-2026-0042');
});

test('remaining balance is total minus paid, rounded to 2 decimal places', () => {
  assert.equal(remainingBalance(100.1, 0.1), 100);
  assert.equal(remainingBalance(1100, 300), 800);
});

test('todayIso formats the local calendar date as YYYY-MM-DD', () => {
  assert.equal(todayIso(new Date(2025, 10, 3, 9, 30)), '2025-11-03');
});

// Invoices API tests using node:test and fetch against an ephemeral-port server.
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';

// Set env before the app (and therefore db.js) is loaded.
process.env.FEESAATHI_DB = ':memory:';
process.env.JWT_SECRET ??= 'test-secret';

const { createApp } = await import('../src/app.js');

let server;
let base;
let cookie;
let studentId;
let invoiceId;
let overdueId;
let draftId;

before(async () => {
  server = createApp().listen(0);
  await new Promise((resolve) => server.once('listening', resolve));
