import { useState } from 'react';

const REQUIRED = ['student_name', 'parent_name', 'parent_mobile', 'fee_amount', 'fee_frequency'];

export const FEE_FREQUENCIES = ['monthly', 'weekly', 'per_class', 'custom'];

// Mirrors the server's required rules. Returns { field: message } for missing fields.
export function validateStudentForm(values) {
  const errors = {};
  for (const name of REQUIRED) {
    const v = values?.[name];
    if (v === undefined || v === null || String(v).trim() === '') {
      errors[name] = 'This field is required';
    }
  }
  return errors;
}

const EMPTY = {
  student_name: '', parent_name: '', parent_mobile: '', email: '', class_grade: '',
  subject: '', joining_date: '', address: '', notes: '', fee_amount: '', fee_frequency: 'monthly',
};

export default function StudentForm({ initial, onSubmit, submitting, onCancel, serverErrors = {}, formError = '' }) {
  const [values, setValues] = useState(() => {
    const start = { ...EMPTY };
    for (const k of Object.keys(EMPTY)) {
      if (initial?.[k] !== undefined && initial?.[k] !== null) start[k] = String(initial[k]);
    }
    return start;
  });
  const [localErrors, setLocalErrors] = useState({});

  function set(name, value) {
    setValues((prev) => ({ ...prev, [name]: value }));
  }

  function handleSubmit(e) {
    e.preventDefault();
    const errs = validateStudentForm(values);
    setLocalErrors(errs);
    if (Object.keys(errs).length === 0) onSubmit(values);
  }

  const errorFor = (name) => localErrors[name] || serverErrors[name];

  function Field({ name, label, required, type = 'text', as, children, ...rest }) {
    const Tag = as || 'input';
    const msg = errorFor(name);
    return (
      <div className="field">
        <label htmlFor={`student-${name}`}>{label}{required ? ' *' : ''}</label>
        <Tag
          id={`student-${name}`}
          name={name}
          type={Tag === 'input' ? type : undefined}
          value={values[name]}
          onChange={(e) => set(name, e.target.value)}
          disabled={submitting}
          {...rest}
        >
          {children}
        </Tag>
        {msg && <div className="field-error">{msg}</div>}
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      {formError && <div className="form-error">{formError}</div>}

      <Field name="student_name" label="Student name" required />
      <Field name="parent_name" label="Parent name" required />
      <Field name="parent_mobile" label="Parent mobile" required type="tel" />
      <Field name="email" label="Email" type="email" />
      <Field name="class_grade" label="Class / grade" />
      <Field name="subject" label="Subject" />
      <Field name="joining_date" label="Joining date" type="date" />
      <Field name="address" label="Address" as="textarea" rows={2} />
      <Field name="notes" label="Notes" as="textarea" rows={2} />
      <Field name="fee_amount" label="Fee amount (₹)" required type="number" min="0" step="any" />
      <Field name="fee_frequency" label="Fee frequency" required as="select">
        {FEE_FREQUENCIES.map((f) => (
          <option key={f} value={f}>{f.replace('_', ' ')}</option>
        ))}
      </Field>

      <div className="inline-field">
        <button type="button" className="btn btn-secondary" onClick={onCancel} disabled={submitting}>
          Cancel
        </button>
        <button type="submit" className="btn btn-primary" disabled={submitting}>
          {submitting ? 'Saving...' : 'Save student'}
        </button>
      </div>
    </form>
  );
}

import { useState } from 'react';

const REQUIRED = ['student_name', 'parent_name', 'parent_mobile', 'fee_amount', 'fee_frequency'];

export const FEE_FREQUENCIES = ['monthly', 'weekly', 'per_class', 'custom'];

// Mirrors the server's required rules. Returns { field: message } for missing fields.
export function validateStudentForm(values) {
  const errors = {};
  for (const name of REQUIRED) {
    const v = values?.[name];
    if (v === undefined || v === null || String(v).trim() === '') {
      errors[name] = 'This field is required';
    }
  }
  return errors;
}

const EMPTY = {
  student_name: '', parent_name: '', parent_mobile: '', email: '', class_grade: '',
  subject: '', joining_date: '', address: '', notes: '', fee_amount: '', fee_frequency: 'monthly',
};

// Defined at module level so inputs keep focus across re-renders.
function Field({ name, label, required, value, onChange, disabled, error, type = 'text', as, children, ...rest }) {
  const Tag = as || 'input';
  return (
    <div className="field">
      <label htmlFor={`student-${name}`}>{label}{required ? ' *' : ''}</label>
      <Tag
        id={`student-${name}`}
        name={name}
        type={Tag === 'input' ? type : undefined}
        value={value}
        onChange={(e) => onChange(name, e.target.value)}
        disabled={disabled}
        {...rest}
      >
        {children}
      </Tag>
      {error && <div className="field-error">{error}</div>}
    </div>
  );
}

export default function StudentForm({ initial, onSubmit, submitting, onCancel, serverErrors = {}, formError = '' }) {
  const [values, setValues] = useState(() => {
    const start = { ...EMPTY };
    for (const k of Object.keys(EMPTY)) {
      if (initial?.[k] !== undefined && initial?.[k] !== null) start[k] = String(initial[k]);
    }
    return start;
  });
  const [localErrors, setLocalErrors] = useState({});

  function set(name, value) {
    setValues((prev) => ({ ...prev, [name]: value }));
  }

  function handleSubmit(e) {
    e.preventDefault();
    const errs = validateStudentForm(values);
    setLocalErrors(errs);
    if (Object.keys(errs).length === 0) onSubmit(values);
  }

  const errorFor = (name) => localErrors[name] || serverErrors[name];
  const common = { value: undefined, onChange: set, disabled: submitting };
  const f = (name) => ({ ...common, value: values[name], error: errorFor(name) });

  return (
    <form onSubmit={handleSubmit} noValidate>
      {formError && <div className="form-error">{formError}</div>}

      <Field name="student_name" label="Student name" required {...f('student_name')} />
      <Field name="parent_name" label="Parent name" required {...f('parent_name')} />
      <Field name="parent_mobile" label="Parent mobile" required type="tel" {...f('parent_mobile')} />
      <Field name="email" label="Email" type="email" {...f('email')} />
      <Field name="class_grade" label="Class / grade" {...f('class_grade')} />
      <Field name="subject" label="Subject" {...f('subject')} />
      <Field name="joining_date" label="Joining date" type="date" {...f('joining_date')} />
      <Field name="address" label="Address" as="textarea" rows={2} {...f('address')} />
      <Field name="notes" label="Notes" as="textarea" rows={2} {...f('notes')} />
      <Field name="fee_amount" label="Fee amount (₹)" required type="number" min="0" step="any" {...f('fee_amount')} />
      <Field name="fee_frequency" label="Fee frequency" required as="select" {...f('fee_frequency')}>
        {FEE_FREQUENCIES.map((opt) => (
          <option key={opt} value={opt}>{opt.replace('_', ' ')}</option>
        ))}
      </Field>

      <div className="inline-field">
        <button type="button" className="btn btn-secondary" onClick={onCancel} disabled={submitting}>
          Cancel
        </button>
        <button type="submit" className="btn btn-primary" disabled={submitting}>
          {submitting ? 'Saving...' : 'Save student'}
        </button>
      </div>
    </form>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api } from '../api.js';
import StudentForm from './StudentForm.jsx';

const FILTERS = [
  { value: 'active', label: 'Active' },
  { value: 'archived', label: 'Archived' },
  { value: 'all', label: 'All' },
];

// Drop empty optional fields and convert the fee to a number before POST.
function toPayload(values) {
  const out = {};
  for (const [k, v] of Object.entries(values)) {
    const t = typeof v === 'string' ? v.trim() : v;
    if (t === '' || t === null || t === undefined) continue;
    out[k] = k === 'fee_amount' ? Number(t) : t;
  }
  return out;
}

// Accepts either { field: msg } or [{ field, message }] from the server.
function normalizeFieldErrors(raw) {
  if (!raw) return {};
  if (Array.isArray(raw)) {
    const out = {};
    for (const item of raw) {
      const key = item.field || item.path;
      if (key && !out[key]) out[key] = item.message || String(item);
    }
    return out;
  }
  const out = {};
  for (const [k, v] of Object.entries(raw)) out[k] = Array.isArray(v) ? v[0] : String(v);
  return out;
}

export default function Students() {
  const [students, setStudents] = useState([]);
  const [status, setStatus] = useState('active');
  const [q, setQ] = useState('');
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [reloadKey, setReloadKey] = useState(0);
  const [showForm, setShowForm] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError] = useState('');
  const [formErrors, setFormErrors] = useState({});

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setLoadError('');
    const params = new URLSearchParams({ status });
    if (q.trim()) params.set('q', q.trim());
    api(`/api/students?${params}`)
      .then((data) => {
        if (!cancelled) setStudents(Array.isArray(data) ? data : data.students || []);
      })
      .catch((err) => {
        if (!cancelled) setLoadError(err.message);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => { cancelled = true; };
  }, [status, q, reloadKey]);

  async function handleCreate(values) {
    setSubmitting(true);
    setFormError('');
    setFormErrors({});
    try {
      await api('/api/students', { method: 'POST', body: toPayload(values) });
      setShowForm(false);
      setReloadKey((k) => k + 1);
    } catch (err) {
      setFormError(err.message);
      setFormErrors(normalizeFieldErrors(err.fieldErrors));
    } finally {
      setSubmitting(false);
    }
  }

  function closeForm() {
    setShowForm(false);
    setFormError('');
    setFormErrors({});
  }

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 12 }}>
        <h1 className="page-title">Students</h1>
        {!showForm && (
          <button type="button" className="btn btn-primary" onClick={() => setShowForm(true)}>
            + Add Student
          </button>
        )}
      </div>

      {showForm && (
        <div className="card">
          <h2 style={{ marginTop: 0 }}>Add student</h2>
          <StudentForm
            onSubmit={handleCreate}
            submitting={submitting}
            onCancel={closeForm}
            formError={formError}
            serverErrors={formErrors}
          />
        </div>
      )}

      <div className="field">
        <label htmlFor="student-search">Search</label>
        <input
          id="student-search"
          type="search"
          placeholder="Name, parent or mobile"
          value={q}
          onChange={(e) => setQ(e.target.value)}
        />
      </div>

      <div role="group" aria-label="Status filter" style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
        {FILTERS.map((f) => {
          const active = status === f.value;
          return (
            <button
              key={f.value}
              type="button"
              aria-pressed={active}
              className={active ? 'btn btn-primary' : 'btn btn-secondary'}
              style={{ flex: 1, padding: '8px 10px', fontSize: '0.9rem' }}
              onClick={() => setStatus(f.value)}
            >
              {f.label}
            </button>
          );
        })}
      </div>

      {loading && <p>Loading students...</p>}
      {!loading && loadError && <div className="form-error">{loadError}</div>}

      {!loading && !loadError && students.length === 0 && (
        <div className="card">
          <p style={{ margin: 0 }}>
            {q.trim() || status !== 'all'
              ? 'No students match this search or filter.'
              : 'No students yet. Tap "+ Add Student" to add your first one.'}
          </p>
        </div>
      )}

      {!loading && !loadError && students.map((s) => (
        <Link
          key={s.id}
          to={`/students/${s.id}`}
          className="card"
          style={{ display: 'block', color: '#0B1F3A', textDecoration: 'none' }}
        >
          <h2 style={{ margin: '0 0 4px', fontSize: '1.1rem' }}>{s.student_name}</h2>
          <div>Parent: {s.parent_name}</div>
          <div>Mobile: {s.parent_mobile}</div>
          <div>Fee: ₹{s.fee_amount} / {String(s.fee_frequency || '').replace('_', ' ')}</div>
        </Link>
      ))}
    </div>
  );
}

