import { Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from './AuthContext.jsx';
import AppShell from './components/AppShell.jsx';
import Login from './pages/Login.jsx';
import Register from './pages/Register.jsx';
import ForgotPassword from './pages/ForgotPassword.jsx';
import ResetPassword from './pages/ResetPassword.jsx';
import Onboarding from './pages/Onboarding.jsx';
import Home from './pages/Home.jsx';
import Settings from './pages/Settings.jsx';
import More from './pages/More.jsx';
import Placeholder from './pages/Placeholder.jsx';

function Loading() { return <div className="center-screen">Loading...</div>; }

function Protected() {
  const { user, profile, loading } = useAuth();
  if (loading) return <Loading />;
  if (!user) return <Navigate to="/login" replace />;
  if (!profile?.onboarded) return <Navigate to="/onboarding" replace />;
  return <AppShell />;
}

function PublicOnly({ children }) {
  const { user, profile, loading } = useAuth();
  if (loading) return <Loading />;
  if (user && profile?.onboarded) return <Navigate to="/home" replace />;
  if (user) return <Navigate to="/onboarding" replace />;
  return children;
}

function OnboardingGate() {
  const { user, profile, loading } = useAuth();
  if (loading) return <Loading />;
  if (!user) return <Navigate to="/login" replace />;
  if (profile?.onboarded) return <Navigate to="/home" replace />;
  return <Onboarding />;
}

export default function App() {
  return (
    <Routes>
      <Route path="/login" element={<PublicOnly><Login /></PublicOnly>} />
      <Route path="/register" element={<PublicOnly><Register /></PublicOnly>} />
      <Route path="/forgot-password" element={<ForgotPassword />} />
      <Route path="/reset-password" element={<ResetPassword />} />
      <Route path="/onboarding" element={<OnboardingGate />} />
      <Route path="/" element={<Protected />}>
        <Route index element={<Navigate to="/home" replace />} />
        <Route path="home" element={<Home />} />
        <Route path="students" element={<Placeholder title="Students" />} />
        <Route path="invoices" element={<Placeholder title="Invoices" />} />
        <Route path="cash-flow" element={<Placeholder title="Cash Flow" />} />
        <Route path="more" element={<More />} />
        <Route path="more/payments" element={<Placeholder title="Payments" />} />
        <Route path="more/expenses" element={<Placeholder title="Expenses" />} />
        <Route path="more/bills" element={<Placeholder title="Bills" />} />
        <Route path="more/reports" element={<Placeholder title="Reports" />} />
        <Route path="more/ai" element={<Placeholder title="FeeSaathi AI" />} />
        <Route path="more/settings" element={<Settings />} />
      </Route>
      <Route path="*" element={<Navigate to="/home" replace />} />
    </Routes>
  );
}

