.bottom-nav {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  width: 100%;
  display: flex;
  background: #FFFFFF;
  border-top: 1px solid #E2E8F0;
  height: 64px;
  z-index: 10;
}

.bottom-nav a {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  color: #64748B;
  text-decoration: none;
  gap: 2px;
}

.bottom-nav a .nav-icon {
  font-size: 1.1rem;
  line-height: 1;
}

.bottom-nav a.active {
  color: #3B9EFF;
  font-weight: 600;
}

/* ---------- Stepper (onboarding) ---------- */

.stepper {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 16px;
}

.step {
