  border-bottom-color: #3B9EFF;
  font-weight: 600;
}

/* ---------- Buttons ---------- */

.btn {
  display: inline-block;
  padding: 12px 16px;
  border-radius: 12px;
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  border: 1px solid transparent;
  text-align: center;
  font-family: inherit;
}

.btn:disabled {
