  cursor: not-allowed;
}

.btn-primary {
  background: #3B9EFF;
  color: #FFFFFF;
}

.btn-secondary {
  background: #FFFFFF;
  color: #0B1F3A;
  border: 1px solid #CBD5E1;
}

/* ---------- Forms ---------- */

.field {
  display: block;
