                  onChange={setPayField} disabled={payBusy} error={payErrors.notes} />
                <button type="button" className="btn btn-primary" onClick={recordPayment} disabled={payBusy}>
                  {payBusy ? 'Recording...' : 'Record payment'}
                </button>
