// Pure reminder rules: which kind of reminder an invoice needs and the draft message text. No database access.

const DAY_MS = 24 * 60 * 60 * 1000;
const UPCOMING_WINDOW_DAYS = 3;
const SKIP_STATUSES = ['cancelled', 'paid', 'draft'];

const money = new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 });

// YYYY-MM-DD to a UTC day number, so date differences are whole days.
const dayNumber = (iso) => {
  const [y, m, d] = iso.split('-').map(Number);
  return Date.UTC(y, m - 1, d) / DAY_MS;
};

// Returns 'overdue', 'partial', 'upcoming' or null (no reminder needed).
export function chooseReminderKind({ status, dueDate, today, remainingBalance, paidAmount }) {
  if (status === 'overdue') return 'overdue';
  if (SKIP_STATUSES.includes(status)) return null;
  if (paidAmount > 0 && remainingBalance > 0) return 'partial';
  const daysUntilDue = dayNumber(dueDate) - dayNumber(today);
  if (daysUntilDue >= 0 && daysUntilDue <= UPCOMING_WINDOW_DAYS) return 'upcoming';
  return null;
}

// Message text for a reminder of the given kind.
export function draftReminder({ kind, studentName, billingPeriod, dueDate, remainingBalance }) {
  const rupees = money.format(remainingBalance);
  switch (kind) {
    case 'upcoming':
      return `Hello! This is a gentle reminder that ${studentName}'s tuition fee for ${billingPeriod} is due on ${dueDate}. Kindly arrange the payment at your convenience. Thank you!`;
    case 'overdue':
      return `Hello! We would like to remind you that ${studentName}'s tuition fee of ${rupees} is still pending. Kindly let us know when we can expect the payment. Thank you for your cooperation.`;
    case 'partial':
      return `Hello! Thank you for the payment received. The remaining tuition fee balance for ${studentName} is ${rupees}. Kindly arrange the remaining payment when convenient.`;
    default:
      throw new Error(`Unknown reminder kind: ${kind}`);
  }
}

// Reminders: drafted messages about an invoice balance. Nothing is sent externally; marking one sent
// only records that the tutor shared it. Mounted behind requireAuth in app.js, so req.userId is the tutor.
import { Router } from 'express';
import { getDb } from '../db.js';
import { findOwnedInvoice, invoiceView } from './invoices.js';
import { chooseReminderKind, draftReminder } from '../reminderLogic.js';
import { todayIso } from '../invoiceLogic.js';

const router = Router();
const KINDS = ['upcoming', 'overdue', 'partial'];
const INVOICE_NOT_FOUND = { message: 'Invoice not found' };
const REMINDER_NOT_FOUND = { message: 'Reminder not found' };

// Optional positive integer query value: null when absent, NaN when invalid.
const optionalId = (raw) => {
  if (raw === undefined || raw === '') return null;
  const n = Number(raw);
  return Number.isInteger(n) && n > 0 ? n : NaN;
};

// Parses :id; returns the reminder row only if it belongs to the current user.
function findOwnedReminder(db, userId, rawId) {
  const id = Number(rawId);
  if (!Number.isInteger(id) || id <= 0) return undefined;
  return db.prepare('SELECT * FROM reminders WHERE id = ? AND user_id = ?').get(id, userId);
}

// POST /api/reminders/draft  { invoice_id, kind?, force? }
router.post('/draft', (req, res) => {
  const body = req.body || {};
  const db = getDb();
  const row = findOwnedInvoice(db, req.userId, body.invoice_id);
  if (!row) return res.status(404).json(INVOICE_NOT_FOUND);
  const invoice = invoiceView(db, row);

  const override = body.kind === undefined || body.kind === null ? null : body.kind;
  if (override !== null && !KINDS.includes(override)) {
    return res.status(400).json({ message: `kind must be one of ${KINDS.join(', ')}` });
  }
  const kind = override ?? chooseReminderKind({
    status: invoice.status,
    dueDate: invoice.due_date,
    today: todayIso(),
    remainingBalance: invoice.remaining_balance,
    paidAmount: invoice.paid_amount,
  });
  if (!kind) return res.status(400).json({ message: 'No reminder is needed for this invoice' });

  // Avoid repeat reminders within 24 hours unless the tutor forces one. created_at is UTC text.
  if (body.force !== true) {
    const recent = db.prepare(`
      SELECT id FROM reminders
      WHERE invoice_id = ? AND user_id = ? AND created_at >= datetime('now', '-1 day')
      LIMIT 1
    `).get(invoice.id, req.userId);
    if (recent) {
      return res.status(409).json({ message: 'A reminder for this invoice was created in the last 24 hours' });
    }
  }

  const student = db.prepare('SELECT student_name FROM students WHERE id = ?').get(invoice.student_id);
  const message = draftReminder({
    kind,
    studentName: student.student_name,
    billingPeriod: invoice.billing_period,
    dueDate: invoice.due_date,
    remainingBalance: invoice.remaining_balance,
  });

  const info = db.prepare(`
    INSERT INTO reminders (user_id, invoice_id, student_id, kind, message, status)
    VALUES (?, ?, ?, ?, ?, 'drafted')
  `).run(req.userId, invoice.id, invoice.student_id, kind, message);
  const reminder = db.prepare('SELECT * FROM reminders WHERE id = ?').get(info.lastInsertRowid);
  return res.status(201).json({ reminder });
});

// GET /api/reminders?invoiceId=&studentId=  (newest first)
router.get('/', (req, res) => {
  const invoiceId = optionalId(req.query.invoiceId);
  const studentId = optionalId(req.query.studentId);
  if (Number.isNaN(invoiceId) || Number.isNaN(studentId)) {
    return res.status(400).json({ message: 'invoiceId and studentId must be positive integers' });
  }

  const params = [req.userId];
  let sql = 'SELECT * FROM reminders WHERE user_id = ?';
  if (invoiceId !== null) {
    sql += ' AND invoice_id = ?';
    params.push(invoiceId);
  }
  if (studentId !== null) {
    sql += ' AND student_id = ?';
    params.push(studentId);
  }
  sql += ' ORDER BY created_at DESC, id DESC';

  const reminders = getDb().prepare(sql).all(...params);
  return res.json({ reminders });
});

// POST /api/reminders/:id/sent  (records that the tutor shared the drafted message)
router.post('/:id/sent', (req, res) => {
  const db = getDb();
  const existing = findOwnedReminder(db, req.userId, req.params.id);
  if (!existing) return res.status(404).json(REMINDER_NOT_FOUND);

  db.prepare("UPDATE reminders SET status = 'sent', sent_at = datetime('now') WHERE id = ? AND user_id = ?")
    .run(existing.id, req.userId);
  const reminder = db.prepare('SELECT * FROM reminders WHERE id = ?').get(existing.id);
  return res.json({ reminder });
});

export default router;

// Pure reminder rules: kind selection and draft text. No database needed.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { chooseReminderKind, draftReminder } from '../src/reminderLogic.js';

const base = { dueDate: '2099-03-31', today: '2099-03-28', remainingBalance: 500, paidAmount: 0 };

test('an overdue invoice needs an overdue reminder', () => {
  assert.equal(chooseReminderKind({ ...base, status: 'overdue' }), 'overdue');
});

test('a part-paid invoice with a balance needs a partial reminder', () => {
  assert.equal(
    chooseReminderKind({ ...base, status: 'partially_paid', paidAmount: 300, remainingBalance: 700 }),
    'partial',
  );
});

test('an invoice due within 3 days needs an upcoming reminder', () => {
  assert.equal(chooseReminderKind({ ...base, status: 'pending' }), 'upcoming');
  assert.equal(chooseReminderKind({ ...base, status: 'pending', today: '2099-03-31' }), 'upcoming');
});

test('an invoice due more than 3 days away needs no reminder', () => {
  assert.equal(chooseReminderKind({ ...base, status: 'pending', today: '2099-03-27' }), null);
});

test('paid, cancelled and draft invoices need no reminder', () => {
  assert.equal(chooseReminderKind({ ...base, status: 'paid', remainingBalance: 0, paidAmount: 1000 }), null);
  assert.equal(chooseReminderKind({ ...base, status: 'cancelled' }), null);
  assert.equal(chooseReminderKind({ ...base, status: 'draft' }), null);
});

test('an overdue draft message contains the rupee amount remaining', () => {
  const text = draftReminder({
    kind: 'overdue',
    studentName: 'Riya Sharma',
    billingPeriod: 'November 2099',
    dueDate: '2099-03-31',
    remainingBalance: 1500,
  });
  assert.ok(text.includes('₹1,500'), text);
  assert.ok(text.includes("Riya Sharma's"));
});

