  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  width: 100%;
  display: flex;
  background: #FFFFFF;
  border-top: 1px solid #E2E8F0;
  height: 64px;
  z-index: 10;
}

.bottom-nav a {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  color: #64748B;
  text-decoration: none;
  gap: 2px;
}

.bottom-nav a .nav-icon {
  font-size: 1.1rem;
  line-height: 1;
}

.bottom-nav a.active {
  color: #3B9EFF;
  font-weight: 600;
}

/* ---------- Stepper (onboarding) ---------- */

.stepper {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 16px;
}

.step {
  flex: 1;
  text-align: center;
  font-size: 0.75rem;
  color: #64748B;
  padding: 6px 4px;
  border-bottom: 3px solid #E2E8F0;
}

.step.active {
  color: #3B9EFF;
  border-bottom-color: #3B9EFF;
  font-weight: 600;
}

/* ---------- Buttons ---------- */

.btn {
  display: inline-block;
  padding: 12px 16px;
  border-radius: 12px;
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  border: 1px solid transparent;
  text-align: center;
  font-family: inherit;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.btn-primary {
  background: #3B9EFF;
  color: #FFFFFF;
}

.btn-secondary {
  background: #FFFFFF;
  color: #0B1F3A;
  border: 1px solid #CBD5E1;
}

/* ---------- Forms ---------- */

.field {
  display: block;
  width: 100%;
  margin-bottom: 12px;
}

.field label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.field input,
.field select,
.field textarea {
  display: block;
  width: 100%;
  padding: 10px;
  border: 1px solid #CBD5E1;
  border-radius: 10px;
  font-size: 1rem;
  font-family: inherit;
  background: #FFFFFF;
}

.inline-field {
  display: flex;
  gap: 12px;
  align-items: flex-end;
}

.inline-field > * {
  flex: 1;
}

/* ---------- Desktop ---------- */

@media (min-width: 900px) {
  .app-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
    padding: 12px 24px;
  }

  .bottom-nav {
    position: static;
    width: auto;
    height: auto;
    border-top: none;
    background: transparent;
    flex: 1;
    justify-content: flex-end;
    gap: 8px;
  }

  .bottom-nav a {
    flex: 0 0 auto;
    flex-direction: row;
    font-size: 0.9rem;
    color: #CBD5E1;
    padding: 8px 12px;
    border-radius: 8px;
    gap: 6px;
  }

  .bottom-nav a.active {
    color: #FFFFFF;
    background: #3B9EFF;
  }

  .app-main {
    max-width: 1100px;
    margin: 0 auto;
    padding: 24px 16px 16px;
  }
}

