import { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api } from '../api.js';

const PRIORITY = {
  high: { label: 'High', bg: '#FDECEC', fg: '#D64545' },
  medium: { label: 'Medium', bg: '#FFF4E5', fg: '#B45309' },
  low: { label: 'Low', bg: '#EEF2F6', fg: '#475569' },
};

const CHANNEL_LABELS = { in_app: 'In app', push: 'Push' };

function deliveryText(row) {
  const channel = CHANNEL_LABELS[row.channel] || row.channel;
  return `${channel}: ${row.status}${row.detail ? ` (${row.detail})` : ''}`;
}

export default function Alerts() {
  const [alerts, setAlerts] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [actionError, setActionError] = useState('');
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    try {
      const data = await api('/api/alerts');
      setAlerts(data.alerts || []);
      setUnreadCount(Number(data.unread_count) || 0);
      setLoadError('');
    } catch (err) {
      setLoadError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  async function markRead(id) {
    setBusy(true);
    setActionError('');
    try {
      await api(`/api/alerts/${id}/read`, { method: 'POST' });
      await load();
    } catch (err) {
      setActionError(err.message);
    } finally {
      setBusy(false);
    }
  }

  async function markAllRead() {
    setBusy(true);
    setActionError('');
    try {
      await api('/api/alerts/read-all', { method: 'POST' });
      await load();
    } catch (err) {
      setActionError(err.message);
    } finally {
      setBusy(false);
    }
  }

  return (
    <div>
      <h1 className="page-title">Alerts</h1>

      <div className="card" style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
        <div>
          <div style={{ fontSize: '0.9rem', color: '#555' }}>Unread</div>
          <div style={{ fontSize: '1.5rem', fontWeight: 700 }}>{unreadCount}</div>
        </div>
        <button
          type="button"
          className="btn btn-secondary"
          disabled={busy || unreadCount === 0}
          onClick={markAllRead}
        >
          Mark all read
        </button>
      </div>

      {loading && <p>Loading alerts...</p>}
      {!loading && loadError && <div className="form-error">{loadError}</div>}
      {actionError && <div className="form-error">{actionError}</div>}

      {!loading && !loadError && alerts.length === 0 && (
        <div className="card">
          <p style={{ margin: 0 }}>No alerts right now.</p>
        </div>
      )}

      {!loading && !loadError && alerts.map((alert) => {
        const p = PRIORITY[alert.priority] || PRIORITY.low;
        const unread = !alert.read;
        return (
          <div
            key={alert.id}
            className="card"
            style={{ opacity: unread ? 1 : 0.75 }}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
              <span
                style={{
                  background: p.bg,
                  color: p.fg,
                  fontSize: '0.75rem',
                  fontWeight: 700,
                  padding: '2px 8px',
                  borderRadius: 999,
                }}
              >
                {p.label}
              </span>
              {unread && (
                <span
                  aria-label="Unread"
                  style={{ width: 8, height: 8, borderRadius: '50%', background: '#3B9EFF', display: 'inline-block' }}
                />
              )}
              <span style={{ fontSize: '0.8rem', color: '#555', marginLeft: 'auto' }}>
                {unread ? 'Unread' : 'Read'}
              </span>
            </div>

            <div style={{ fontWeight: unread ? 700 : 400 }}>{alert.message}</div>

            {Array.isArray(alert.delivery) && alert.delivery.length > 0 && (
              <ul style={{ margin: '8px 0 0', paddingLeft: 18, fontSize: '0.85rem', color: '#555' }}>
                {alert.delivery.map((row, i) => (
                  <li key={`${row.channel}-${i}`}>{deliveryText(row)}</li>
                ))}
              </ul>
            )}

            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 12 }}>
              {alert.action_path && (
                <Link className="btn btn-primary" to={alert.action_path} style={{ textDecoration: 'none' }}>
                  {alert.action_label || 'Open'}
                </Link>
              )}
              {unread && (
                <button
                  type="button"
                  className="btn btn-secondary"
                  disabled={busy}
                  onClick={() => markRead(alert.id)}
                >
                  Mark read
                </button>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

import { useState } from 'react';
import { api } from '../api.js';

const rupees = new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 });

const REPORTS = [
  { value: 'collection', label: 'Collection' },
  { value: 'outstanding', label: 'Outstanding' },
  { value: 'overdue', label: 'Overdue' },
  { value: 'student-wise', label: 'Student-wise' },
  { value: 'expenses', label: 'Expenses' },
  { value: 'upcoming-bills', label: 'Upcoming bills' },
  { value: 'forecast', label: 'Forecast' },
];

function pad(n) {
  return String(n).padStart(2, '0');
}

function localDate(d) {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

function monthStart() {
  const now = new Date();
  return localDate(new Date(now.getFullYear(), now.getMonth(), 1));
}

function monthEnd() {
  const now = new Date();
  return localDate(new Date(now.getFullYear(), now.getMonth() + 1, 0));
}

function header(key) {
  const text = key.replace(/_/g, ' ');
  return text.charAt(0).toUpperCase() + text.slice(1);
}

function cell(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

export default function Reports() {
  const [name, setName] = useState('collection');
  const [from, setFrom] = useState(monthStart);
  const [to, setTo] = useState(monthEnd);
  const [horizon, setHorizon] = useState('30');
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const isForecast = name === 'forecast';

  function buildUrl(format) {
    if (isForecast) {
      return `/api/reports/forecast?horizon=${horizon}&format=${format}`;
    }
    return `/api/reports/${name}?from=${from}&to=${to}&format=${format}`;
  }

  function validate() {
    if (!isForecast && from && to && from > to) {
      return 'The "from" date cannot be after the "to" date.';
    }
    return '';
  }

  async function view() {
    const problem = validate();
    if (problem) {
      setError(problem);
      setResult(null);
      return;
    }
    setLoading(true);
    setError('');
    try {
      const data = await api(buildUrl('json'));
      setResult(data);
    } catch (err) {
      setResult(null);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }

  function downloadCsv() {
    const problem = validate();
    if (problem) {
      setError(problem);
      return;
    }
    setError('');
    const a = document.createElement('a');
    a.href = buildUrl('csv');
    a.download = `${name}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
  }

  const rows = Array.isArray(result?.rows) ? result.rows : [];
  const columns = rows.length > 0 ? Object.keys(rows[0]) : [];
  const total = result?.total;

  return (
    <div>
      <h1 className="page-title">Reports</h1>

      <div className="card">
        <div className="field">
          <label htmlFor="report-name">Report</label>
          <select
            id="report-name"
            value={name}
            onChange={(e) => { setName(e.target.value); setResult(null); setError(''); }}
          >
            {REPORTS.map((r) => (
              <option key={r.value} value={r.value}>{r.label}</option>
            ))}
          </select>
        </div>

        {isForecast ? (
          <div className="field">
            <label htmlFor="report-horizon">Horizon</label>
            <select id="report-horizon" value={horizon} onChange={(e) => setHorizon(e.target.value)}>
              <option value="30">30 days</option>
              <option value="60">60 days</option>
              <option value="90">90 days</option>
            </select>
          </div>
        ) : (
          <div className="inline-field">
            <div className="field">
              <label htmlFor="report-from">From</label>
              <input id="report-from" type="date" value={from} onChange={(e) => setFrom(e.target.value)} />
            </div>
            <div className="field">
              <label htmlFor="report-to">To</label>
              <input id="report-to" type="date" value={to} onChange={(e) => setTo(e.target.value)} />
            </div>
          </div>
        )}

        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
          <button type="button" className="btn btn-primary" disabled={loading} onClick={view}>
            {loading ? 'Loading...' : 'View'}
          </button>
          <button type="button" className="btn btn-secondary" onClick={downloadCsv}>
            Download CSV
          </button>
        </div>
      </div>

      {error && <div className="form-error">{error}</div>}

      {result && (
        <div className="card">
          {total !== undefined && total !== null && (
            <div style={{ marginBottom: 12, fontWeight: 600 }}>
              {typeof total === 'object'
                ? Object.entries(total).map(([key, value]) => (
                    <div key={key}>{header(key)}: {typeof value === 'number' ? rupees.format(value) : cell(value)}</div>
                  ))
                : <div>Total: {typeof total === 'number' ? rupees.format(total) : cell(total)}</div>}
            </div>
          )}

          {rows.length === 0 ? (
            <p style={{ margin: 0 }}>No rows for this period.</p>
          ) : (
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.9rem' }}>
                <thead>
                  <tr>
                    {columns.map((key) => (
                      <th key={key} style={{ textAlign: 'left', borderBottom: '1px solid #E2E8F0', padding: '6px 8px' }}>
                        {header(key)}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row, i) => (
                    <tr key={i}>
                      {columns.map((key) => (
                        <td key={key} style={{ borderBottom: '1px solid #E2E8F0', padding: '6px 8px' }}>
                          {cell(row[key])}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

